/* Pointer effects use animation frames; touch and reduced-motion retain static cards. */
(function(){
 'use strict';
 const root=document.getElementById('site-root');if(!root)return;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const fine=matchMedia('(hover: hover) and (pointer: fine)');
 const header=root.querySelector('.header'),top=root.querySelector('.scroll-top');
 let scrollFrame=0;
 const paintScroll=()=>{scrollFrame=0;header?.classList.toggle('is-scrolled',window.scrollY>30);if(top){const total=document.documentElement.scrollHeight-window.innerHeight;const progress=total>0?Math.min(1,Math.max(0,window.scrollY/total)):0;top.style.setProperty('--scroll-angle',progress*360+'deg');}};
 const onScroll=()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(paintScroll);};
 window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',onScroll,{passive:true});paintScroll();
 root.querySelectorAll('.project-card').forEach(card=>{
  let frame=0,px=.5,py=.5;
  function reset(){cancelAnimationFrame(frame);frame=0;card.classList.remove('is-tilting');card.style.removeProperty('--tilt-x');card.style.removeProperty('--tilt-y');card.style.removeProperty('--image-x');card.style.removeProperty('--image-y');}
  card.addEventListener('pointermove',event=>{
   if(reduced.matches||!fine.matches)return;
   const bounds=card.getBoundingClientRect();px=Math.max(0,Math.min(1,(event.clientX-bounds.left)/bounds.width));py=Math.max(0,Math.min(1,(event.clientY-bounds.top)/bounds.height));
   if(frame)return;frame=requestAnimationFrame(()=>{frame=0;card.classList.add('is-tilting');card.style.setProperty('--tilt-x',(0.5-py)*5+'deg');card.style.setProperty('--tilt-y',(px-0.5)*5+'deg');card.style.setProperty('--image-x',px*100+'%');card.style.setProperty('--image-y',py*100+'%');});
  });
  card.addEventListener('pointerleave',reset);card.addEventListener('pointercancel',reset);reduced.addEventListener('change',reset);fine.addEventListener('change',reset);
 });
 if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>entry.target.classList.toggle('art-in-view',entry.isIntersecting));},{threshold:.15});root.querySelectorAll('.project-art-image').forEach(art=>observer.observe(art));}
 window.addEventListener('pagehide',()=>cancelAnimationFrame(scrollFrame),{once:true});
})();

(function(){
 'use strict';
 const root=document.getElementById('site-root');if(!root)return;
 const glossary={"TTS":["Text to Speech","Generates spoken audio from written text.","Yozma matndan ovozli nutq yaratadi.","Преобразует письменный текст в звучащую речь."],"Local Inference":["Local Model Inference","Runs trained models on local devices or servers to produce responses.","Javob olish uchun tayyor modellarni lokal qurilma yoki serverda ishga tushiradi.","Запускает обученные модели на локальных устройствах или серверах для получения ответов."],"X-ray":["X-ray Imaging","Uses X-ray images to examine internal structures and cargo contents.","Ichki tuzilma va yuk tarkibini tekshirish uchun rentgen tasvirlaridan foydalanadi.","Использует рентгеновские изображения для изучения внутренней структуры и содержимого грузов."],"R&D":["Research and Development","Investigates approaches and develops new technical solutions.","Yondashuvlarni o‘rganish va yangi texnik yechimlarni ishlab chiqish.","Исследование подходов и разработка новых технических решений."],"LLM":["Large Language Model","A model trained on large amounts of text to understand and generate language.","Katta hajmdagi matnlar asosida o‘qitilgan, tilni tushunish va matn yaratishga yordam beradigan model.","Модель, обученная на больших объёмах текста для понимания и генерации языка."],"RAG":["Retrieval-Augmented Generation","Retrieves relevant information from a knowledge source before generating an answer.","Javob yaratishdan oldin bilim manbasidan tegishli ma’lumotlarni topib foydalanish usuli.","Поиск подходящей информации в базе знаний перед формированием ответа моделью."],"AI":["Artificial Intelligence","Software methods that perform tasks such as recognition, prediction and language understanding.","Tanish, bashorat qilish va tilni tushunish kabi vazifalarni bajaruvchi dasturiy usullar.","Программные методы для распознавания, прогнозирования и понимания языка."],"Computer Vision":["Computer Vision","Methods for extracting information from images and video.","Rasm va videolardan ma’lumot ajratib olish usullari.","Методы извлечения информации из изображений и видео."],"STT":["Speech to Text","Converts spoken audio into written text.","Ovozli nutqni yozma matnga aylantiradi.","Преобразование устной речи в текст."],"STT / TTS":["Speech to Text / Text to Speech","Converts speech into text and text into spoken audio.","Nutqni matnga va matnni ovozli nutqqa aylantiradi.","Преобразование речи в текст и текста в звучащую речь."],"Voice AI":["Voice Artificial Intelligence","Combines speech recognition, language processing and speech generation for voice interaction.","Ovozli muloqot uchun nutqni tanish, tilga ishlov berish va nutq yaratishni birlashtiradi.","Объединяет распознавание речи, обработку языка и синтез речи для голосового взаимодействия."],"Local AI":["Locally Deployed AI","Runs AI models on local devices or servers with control over data handling.","Ma’lumotlar bilan ishlashni nazorat qilgan holda AI modellarini lokal qurilma yoki serverda ishga tushirish.","Запуск AI-моделей на локальных устройствах или серверах с контролем обработки данных."],"On-premises":["On-premises Deployment","Software hosted on infrastructure operated within an organisation.","Dasturiy ta’minotni tashkilotning o‘z infratuzilmasida joylashtirish.","Размещение программного обеспечения в инфраструктуре организации."],"Deep Learning":["Deep Learning","Machine learning using neural networks with multiple layers.","Ko‘p qatlamli neyron tarmoqlardan foydalanadigan mashinaviy o‘rganish.","Машинное обучение с использованием многослойных нейронных сетей."],"Research":["Research & Evaluation","Investigating methods and assessing their suitability before practical use.","Usullarni o‘rganish va amaliy qo‘llashdan oldin ularning mosligini baholash.","Исследование методов и оценка их пригодности перед практическим применением."],"vLLM":["vLLM","An engine for serving language models and processing inference requests efficiently.","Til modellarini servis sifatida ishlatish va inferens so‘rovlariga samarali ishlov berish mexanizmi.","Движок для обслуживания языковых моделей и эффективной обработки запросов инференса."],"Docker":["Docker Containers","Packages applications and their dependencies into containers for consistent deployment.","Ilova va uning bog‘liqliklarini bir xil muhitda ishga tushirish uchun konteynerlarga joylaydi.","Упаковывает приложения и зависимости в контейнеры для воспроизводимого развёртывания."],"Qdrant":["Qdrant Vector Database","Stores vectors and retrieves similar items for semantic search and RAG.","Semantik qidiruv va RAG uchun vektorlarni saqlaydi va o‘xshash elementlarni topadi.","Хранит векторы и находит похожие элементы для семантического поиска и RAG."],"Customs Valuation":["Customs Valuation","Determining the customs value of goods using applicable information and valuation methods.","Tegishli ma’lumotlar va baholash usullari asosida tovarning bojxona qiymatini aniqlash.","Определение таможенной стоимости товаров на основе соответствующих сведений и методов оценки."],"Data Analysis":["Data Analysis","Examining data to find patterns and support decisions.","Qonuniyatlarni topish va qarorlarni qo‘llab-quvvatlash uchun ma’lumotlarni o‘rganish.","Изучение данных для выявления закономерностей и поддержки решений."],"OCR":["Optical Character Recognition","Recognises printed or handwritten text in document images.","Hujjat tasvirlaridagi bosma yoki qo‘lyozma matnlarni taniydi.","Распознаёт печатный или рукописный текст на изображениях документов."],"Document AI":["Document Artificial Intelligence","Extracts and analyses text, fields and structure from documents.","Hujjatlardan matn, maydonlar va tuzilmani ajratib, tahlil qiladi.","Извлекает и анализирует текст, поля и структуру документов."],"Text Analysis":["Text Analysis","Processes text to identify meaning, relevant information and patterns.","Mazmun, tegishli ma’lumotlar va qonuniyatlarni aniqlash uchun matnga ishlov beradi.","Обрабатывает текст для выявления смысла, значимой информации и закономерностей."],"Railway":["Railway Technology","Software applications for railway assets and workflows, including wagon identification.","Vagonlarni aniqlash kabi temir yo‘l obyektlari va jarayonlariga oid dasturiy yechimlar.","Программные решения для железнодорожных объектов и процессов, включая идентификацию вагонов."],"Multilingual":["Multilingual Systems","Supports understanding and communication in multiple languages.","Bir nechta tilda tushunish va muloqot qilishni qo‘llab-quvvatlaydi.","Поддерживает понимание и общение на нескольких языках."],"National Legislation":["National Legislation","National laws and regulations used as a reference source for legal information.","Huquqiy ma’lumotlar uchun manba bo‘lib xizmat qiladigan milliy qonun va me’yoriy hujjatlar.","Национальные законы и нормативные акты как источник правовой информации."],"Chatbot":["Conversational Software","An application that interacts with users through text or voice messages.","Foydalanuvchi bilan matnli yoki ovozli xabarlar orqali muloqot qiladigan ilova.","Приложение для взаимодействия с пользователями через текстовые или голосовые сообщения."],"Image Matching":["Image Matching","Compares visual features to assess whether images show corresponding objects.","Tasvirlarda mos obyektlar borligini baholash uchun vizual belgilarni solishtiradi.","Сравнивает визуальные признаки для оценки соответствия объектов на изображениях."],"Multimodal AI":["Multimodal Artificial Intelligence","Works with more than one input type, such as text, images and audio.","Matn, rasm va ovoz kabi bir nechta turdagi ma’lumotlar bilan ishlaydi.","Работает с несколькими типами данных: текстом, изображениями и аудио."],"Sparse Search":["Sparse Retrieval","Retrieves information using sparse representations, often based on keyword signals.","Ko‘pincha kalit so‘z belgilariga asoslangan siyrak ifodalar orqali ma’lumot qidirish.","Поиск с использованием разреженных представлений, часто основанных на ключевых словах."],"Dense Search":["Dense Vector Retrieval","Uses dense vector embeddings to retrieve information with related meaning.","Mazmunan yaqin ma’lumotlarni topish uchun zich vektorli ifodalardan foydalanadi.","Использует плотные векторные представления для поиска информации с близким смыслом."],"Hybrid Search":["Hybrid Retrieval","Combines sparse and dense retrieval to use both keyword and semantic signals.","Kalit so‘z va semantik belgilarni birga ishlatish uchun sparse va dense qidiruvni birlashtiradi.","Объединяет sparse- и dense-поиск, используя ключевые слова и семантические сигналы."],"Face Recognition":["Face Recognition","Compares facial representations to assess identity similarity.","Shaxs o‘xshashligini baholash uchun yuzning vektorli ifodalarini solishtiradi.","Сравнивает представления лиц для оценки сходства личности."],"Embeddings":["Vector Embeddings","Numerical representations of text, images or other data used for comparison and retrieval.","Solishtirish va qidiruv uchun matn, rasm yoki boshqa ma’lumotlarning sonli ifodasi.","Числовые представления текста, изображений и других данных для сравнения и поиска."],"Transformers":["Transformers Library","Tools for loading and using pretrained models for language, vision and audio tasks.","Til, tasvir va ovoz vazifalari uchun tayyor modellarni yuklash va ishlatish vositalari.","Инструменты загрузки и применения предобученных моделей для языка, зрения и аудио."],"PyTorch":["PyTorch","A framework for building, training and running neural networks.","Neyron tarmoqlarni yaratish, o‘qitish va ishga tushirish uchun framework.","Фреймворк для создания, обучения и запуска нейронных сетей."],"Vector Search":["Vector Similarity Search","Finds similar data by comparing numerical vector representations.","Sonli vektorli ifodalarni solishtirib, o‘xshash ma’lumotlarni topadi.","Находит похожие данные сравнением числовых векторных представлений."],"Detection":["Object Detection","Locates objects in images and predicts their categories.","Tasvirdagi obyektlarning joylashuvi va turini aniqlaydi.","Определяет положение объектов на изображении и их категории."],"Classification":["Classification","Assigns input data to defined categories.","Kirish ma’lumotlarini belgilangan toifalarga ajratadi.","Относит входные данные к заданным категориям."],"Python":["Python","A programming language widely used for AI, data processing and backend services.","AI, ma’lumotlarga ishlov berish va backend servislar uchun keng qo‘llanadigan dasturlash tili.","Язык программирования для AI, обработки данных и серверных сервисов."],"Linux":["Linux","An operating system platform widely used for servers, containers and AI infrastructure.","Serverlar, konteynerlar va AI infratuzilmasida keng qo‘llanadigan operatsion tizim platformasi.","Платформа операционных систем для серверов, контейнеров и AI-инфраструктуры."],"GPU":["Graphics Processing Unit","A parallel processor used for graphics and accelerated AI computation.","Grafika va AI hisoblashlarini tezlashtirish uchun ishlatiladigan parallel protsessor.","Параллельный процессор для графики и ускоренных вычислений AI."],"REST APIs":["Representational State Transfer APIs","HTTP interfaces that let software systems exchange data and request operations.","Dasturiy tizimlarga HTTP orqali ma’lumot almashish va amallarni so‘rash imkonini beradigan interfeyslar.","HTTP-интерфейсы для обмена данными и выполнения операций между системами."],"NVIDIA Run:ai":["NVIDIA Run:ai","A platform for orchestrating AI workloads and managing shared GPU resources.","AI ish yuklamalarini orkestratsiya qilish va umumiy GPU resurslarini boshqarish platformasi.","Платформа оркестрации AI-нагрузок и управления общими ресурсами GPU."],"MinIO":["MinIO Object Storage","Object storage with an S3-compatible interface for files and datasets.","Fayl va ma’lumot to‘plamlari uchun S3 bilan mos interfeysli obyekt saqlash tizimi.","Объектное хранилище с S3-совместимым интерфейсом для файлов и наборов данных."],"Redis":["Redis","An in-memory data store used for caching and fast application data access.","Keshlash va ilova ma’lumotlariga tez kirish uchun operativ xotirada ishlaydigan saqlash tizimi.","Хранилище данных в памяти для кеширования и быстрого доступа приложений."],"GPU Inference":["GPU Inference","Runs a trained model on GPU hardware to generate predictions or responses.","Bashorat yoki javob olish uchun o‘qitilgan modelni GPU’da ishga tushirish.","Запуск обученной модели на GPU для получения прогнозов или ответов."],"Model Serving":["Model Serving","Makes a trained model accessible to applications through a service interface.","O‘qitilgan modeldan ilovalar servis interfeysi orqali foydalanishini ta’minlash.","Предоставление приложениям доступа к обученной модели через сервисный интерфейс."],"H200 / B200 Clusters":["NVIDIA GPU Clusters","Multiple GPU servers managed together for AI computation and inference workloads.","AI hisoblashlari va inferens uchun birgalikda boshqariladigan bir nechta GPU serverlari.","Несколько GPU-серверов, управляемых совместно для AI-вычислений и инференса."],"C++":["C++ Programming Language","A compiled language used for performance-sensitive applications and systems software.","Yuqori unumdorlik talab qiladigan ilovalar va tizimli dasturlar uchun kompilyatsiya qilinadigan til.","Компилируемый язык для высокопроизводительных приложений и системного ПО."],"C#":["C Sharp","A programming language in the .NET ecosystem for services and applications.","Servis va ilovalar yaratish uchun .NET ekotizimidagi dasturlash tili.","Язык программирования экосистемы .NET для сервисов и приложений."],"HTML":["HyperText Markup Language","Defines the structure and meaning of web page content.","Web sahifa mazmunining tuzilishi va ma’nosini belgilaydi.","Определяет структуру и смысл содержимого веб-страниц."],"CSS":["Cascading Style Sheets","Controls web page layout, colours, typography and visual effects.","Web sahifa joylashuvi, ranglar, shriftlar va vizual effektlarni boshqaradi.","Управляет компоновкой, цветами, типографикой и эффектами веб-страниц."],"JavaScript":["JavaScript","A programming language for interactive web interfaces and application logic.","Interaktiv web interfeyslar va ilova mantiqi uchun dasturlash tili.","Язык программирования для интерактивных веб-интерфейсов и логики приложений."],"React":["React UI Library","Builds application interfaces from reusable components.","Qayta ishlatiladigan komponentlardan ilova interfeyslarini yaratadi.","Позволяет создавать интерфейсы приложений из повторно используемых компонентов."],"Vue.js":["Vue.js","A framework for building reactive web interfaces and applications.","Reaktiv web interfeyslar va ilovalar yaratish uchun framework.","Фреймворк для создания реактивных веб-интерфейсов и приложений."],"Flutter":["Flutter UI Toolkit","Builds applications for multiple platforms from a shared Dart codebase.","Umumiy Dart kodi asosida bir nechta platforma uchun ilovalar yaratadi.","Создаёт приложения для нескольких платформ на общей кодовой базе Dart."],"Kotlin":["Kotlin","A programming language commonly used for Android development and JVM applications.","Android va JVM ilovalarini yaratishda keng qo‘llanadigan dasturlash tili.","Язык программирования для Android-разработки и JVM-приложений."],"Android Studio":["Android Studio IDE","An integrated environment for developing, debugging and building Android applications.","Android ilovalarini yaratish, xatolarini topish va yig‘ish uchun integratsiyalashgan muhit.","Интегрированная среда разработки, отладки и сборки Android-приложений."],"Local Browser":["Local Browser","A browser application designed for local workflows and controlled environments.","Lokal jarayonlar va nazorat qilinadigan muhitlar uchun mo‘ljallangan brauzer ilovasi.","Браузерное приложение для локальных процессов и контролируемых сред."],"Security":["Software Security","Practices that protect software, access and data from misuse.","Dastur, kirish huquqlari va ma’lumotlarni noto‘g‘ri foydalanishdan himoya qilish amaliyotlari.","Практики защиты программ, доступа и данных от неправомерного использования."],"Application Development":["Application Development","Designing, implementing and maintaining software applications.","Dasturiy ilovalarni loyihalash, yaratish va qo‘llab-quvvatlash.","Проектирование, разработка и сопровождение программных приложений."]};
 const aliases={'CV':'Computer Vision','Local-first AI':'Local AI','Multimodal systems':'Multimodal AI','Production engineering':'Application Development','AI & Machine Learning':'AI','AI va Machine Learning':'AI','AI и машинное обучение':'AI','Software Development':'Application Development','Dasturiy ta’minot':'Application Development','Разработка ПО':'Application Development','NVIDIA GPU Infrastructure':'GPU','NVIDIA GPU infratuzilmasi':'GPU','GPU-инфраструктура NVIDIA':'GPU'};
 const dialog=document.createElement('dialog');dialog.className='tag-dialog';dialog.setAttribute('aria-labelledby','tag-info-title');dialog.innerHTML='<button type="button" class="tag-dialog-close" aria-label="Close">×</button><div class="overline" id="tag-info-label"></div><h2 id="tag-info-title"></h2><p class="tag-full-name"></p><p class="tag-info-description"></p><button type="button" class="button button-primary tag-dialog-done"></button>';root.append(dialog);
 let source=null;
 const labels={en:['TECHNOLOGY EXPLAINED','Close'],uz:['TEXNOLOGIYA HAQIDA','Yopish'],ru:['О ТЕХНОЛОГИИ','Закрыть']};
 function close(){dialog.close();}
 dialog.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close();}});
 dialog.querySelector('.tag-dialog-close').addEventListener('click',close);dialog.querySelector('.tag-dialog-done').addEventListener('click',close);
 dialog.addEventListener('click',event=>{const r=dialog.getBoundingClientRect();if(event.target===dialog&&(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom))close();});
 dialog.addEventListener('close',()=>{if(!root.querySelector('.modal-backdrop:not([hidden])'))document.body.classList.remove('modal-open');source?.focus();});
 function entry(key){if(glossary[key])return glossary[key];if(/^(RTX |H200$|B200$)/.test(key))return ['NVIDIA '+key,'NVIDIA GPU hardware used for accelerated AI computation and inference.','AI hisoblashlari va inferensni tezlashtirishda ishlatiladigan NVIDIA GPU qurilmasi.','GPU NVIDIA для ускоренных AI-вычислений и инференса.'];return null;}
 function open(button){const key=button.dataset.tech;const info=entry(key);if(!info)return;source=button;const lang=document.documentElement.lang||'en',index=({en:1,uz:2,ru:3})[lang]||1;const text=labels[lang]||labels.en;dialog.querySelector('#tag-info-label').textContent=text[0];dialog.querySelector('#tag-info-title').textContent=key;dialog.querySelector('.tag-full-name').textContent=info[0];dialog.querySelector('.tag-info-description').textContent=info[index];dialog.querySelector('.tag-dialog-done').textContent=text[1];dialog.querySelector('.tag-dialog-close').setAttribute('aria-label',text[1]);dialog.showModal();document.body.classList.add('modal-open');dialog.querySelector('.tag-dialog-close').focus();}
 function prepare(){root.querySelectorAll('.tags>span,.skill-tags>span,.stack-chips>span,.modal-tags>span,.hero-pills>span,.floating-tech,.gpu-chip strong').forEach(tag=>{if(tag.dataset.tech)return;const raw=tag.textContent.trim().replace(/^(<\/>|✦|⌘)\s*/,''),key=aliases[raw]||raw;if(!entry(key))return;tag.dataset.tech=key;tag.setAttribute('role','button');tag.setAttribute('tabindex','0');tag.setAttribute('aria-haspopup','dialog');tag.classList.add('technology-tag');tag.removeAttribute('aria-hidden');if(tag.parentElement?.classList.contains('gpu-chip'))tag.parentElement.removeAttribute('aria-hidden');});}
 root.addEventListener('click',event=>{const button=event.target.closest('[data-tech]');if(!button)return;event.preventDefault();event.stopPropagation();open(button);},true);
 root.addEventListener('keydown',event=>{const button=event.target.closest('[data-tech]');if(!button||!['Enter',' '].includes(event.key))return;event.preventDefault();event.stopPropagation();open(button);},true);
 new MutationObserver(prepare).observe(root,{childList:true,subtree:true});prepare();
})();
